/**
 * WB Seller Auth — CDP-based approach.
 * Opens headless browser, lets F.A.C.C.T. antibot generate captcha_token,
 * then makes direct fetch() calls from inside the page.
 * No DOM manipulation, no InputCell, no button clicks.
 */
import puppeteer, { type Browser, type Page } from "puppeteer";
import path from "path";
import fs from "fs";
import { saveAuthTokensCommon, checkApiSession } from "./wb-seller-api";

const DATA_DIR = path.join(process.cwd(), "data");
const SELLER_AUTH_URL = "https://seller-auth.wildberries.ru/";

// Singleton (survives hot-reload)
const g = globalThis as unknown as {
  __wbCdpBrowser?: Browser | null;
  __wbCdpPage?: Page | null;
  __wbCdpSticker?: string;
};

function ensureDirs() {
  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
}

async function getBrowser(): Promise<Browser> {
  const existing = g.__wbCdpBrowser;
  if (existing && existing.connected) return existing;
  const browser = await puppeteer.launch({
    headless: "new" as unknown as boolean,
    args: [
      "--no-sandbox",
      "--disable-setuid-sandbox",
      "--disable-dev-shm-usage",
      "--disable-blink-features=AutomationControlled",
      "--window-size=1280,900",
    ],
  });
  g.__wbCdpBrowser = browser;
  return browser;
}

async function getPage(): Promise<Page> {
  const browser = await getBrowser();
  const existing = g.__wbCdpPage;
  if (existing && !existing.isClosed()) return existing;
  const pages = await browser.pages();
  const page = pages.length > 0 ? pages[0] : await browser.newPage();
  await page.setViewport({ width: 1280, height: 800 });
  await page.evaluateOnNewDocument(() => {
    Object.defineProperty(navigator, "webdriver", { get: () => false });
  });
  g.__wbCdpPage = page;
  return page;
}

async function closeBrowser() {
  const pg = g.__wbCdpPage;
  if (pg && !pg.isClosed()) { await pg.close().catch(() => {}); g.__wbCdpPage = null; }
  const br = g.__wbCdpBrowser;
  if (br && br.connected) { await br.close().catch(() => {}); g.__wbCdpBrowser = null; }
}

// --- Types ---

export type AuthStepResult = {
  ok: boolean;
  step: "code" | "captcha" | "authenticated" | "error";
  captchaImage?: string;
  error?: string;
  warning?: string;
  debug?: unknown;
};

// --- Step 1: Send phone ---

export async function cdpSendPhone(phone: string): Promise<AuthStepResult> {
  try {
    // Clean phone: +79991234567 → 79991234567
    let digits = phone.replace(/\D/g, "");
    if (digits.startsWith("8") && digits.length === 11) digits = "7" + digits.slice(1);
    if (!digits.startsWith("7")) digits = "7" + digits;

    const page = await getPage();

    // Load WB auth page — this triggers F.A.C.C.T. antibot SDK
    console.log("[wb-auth-cdp] Loading auth page...");
    await page.goto(SELLER_AUTH_URL, { waitUntil: "networkidle2", timeout: 30000 });

    // Wait for antibot SDK to initialize
    console.log("[wb-auth-cdp] Waiting for antibot SDK...");
    await page.waitForFunction(() => {
      return typeof (window as unknown as Record<string, unknown>).gib !== "undefined";
    }, { timeout: 15000 }).catch(() => {
      console.warn("[wb-auth-cdp] Antibot SDK (window.gib) not found");
    });

    // Extra wait for SDK to fully initialize
    await new Promise(r => setTimeout(r, 3000));

    // Intercept the captcha_token from outgoing requests via CDP
    const client = await page.createCDPSession();
    await client.send("Network.enable");

    let interceptedCaptchaToken = "";
    const tokenPromise = new Promise<string>((resolve) => {
      const timeout = setTimeout(() => resolve(""), 30000);
      client.on("Network.requestWillBeSent", (params: { request: { url: string; postData?: string } }) => {
        if (params.request.url.includes("/code/wb-captcha") && params.request.postData) {
          try {
            const body = JSON.parse(params.request.postData);
            if (body.captcha_token && body.captcha_token.length > 10) {
              clearTimeout(timeout);
              resolve(body.captcha_token);
            }
          } catch {}
        }
      });
    });

    // Now interact with the page — type phone and submit via the real UI
    // This lets the antibot SDK generate the token naturally
    console.log("[wb-auth-cdp] Entering phone via page UI...");

    // Wait for phone input
    const phoneSelector = 'input[class*="SimpleInput"], input[inputmode="numeric"], input[placeholder*="999"]';
    await page.waitForSelector(phoneSelector, { timeout: 15000 });
    const phoneInput = await page.$(phoneSelector);
    if (!phoneInput) {
      await client.send("Network.disable");
      await client.detach();
      return { ok: false, step: "error", error: "Не найдено поле ввода телефона" };
    }

    // WB already has +7 prefix — type only 10 digits
    let phoneDigits = digits;
    if (phoneDigits.startsWith("7") && phoneDigits.length === 11) phoneDigits = phoneDigits.slice(1);

    await phoneInput.click({ clickCount: 3 });
    await phoneInput.type(phoneDigits, { delay: 80 });
    await new Promise(r => setTimeout(r, 500));

    // Click submit button
    const btn = await page.$('button[type="submit"]');
    if (btn) {
      await btn.click();
    } else {
      await page.keyboard.press("Enter");
    }

    // Wait for the antibot to generate token and WB to send the request
    console.log("[wb-auth-cdp] Waiting for captcha_token from antibot...");
    interceptedCaptchaToken = await tokenPromise;
    console.log("[wb-auth-cdp] Captcha token intercepted:", interceptedCaptchaToken ? interceptedCaptchaToken.slice(0, 50) + "..." : "empty");

    await client.send("Network.disable");
    await client.detach();

    // Now wait for the page to react — check what appeared
    await new Promise(r => setTimeout(r, 3000));

    // Check page state
    const result = await page.evaluate(() => {
      const bodyText = document.body.innerText || "";
      const rateLimitMatch = bodyText.match(/Запрос кода возможен через\s+(.+)/i);
      if (rateLimitMatch) return { type: "ratelimit", text: rateLimitMatch[1].trim().split("\n")[0] };
      if (bodyText.includes("Введите код") || bodyText.includes("код из СМС")) return { type: "code" };
      if (bodyText.toLowerCase().includes("captcha")) return { type: "captcha" };
      return { type: "unknown", text: bodyText.slice(0, 200) };
    });

    console.log("[wb-auth-cdp] Page state:", result.type);

    if (result.type === "ratelimit") {
      await closeBrowser();
      return { ok: false, step: "error", error: `WB заблокировал отправку кода. Повтор через ${result.text}` };
    }

    if (result.type === "code") {
      return { ok: true, step: "code" };
    }

    if (result.type === "captcha") {
      // Slide captcha appeared — it's interactive, user can't solve it from our UI
      return { ok: false, step: "error", error: "WB показал slide-капчу. Попробуйте ещё раз." };
    }

    // Unknown state
    return { ok: true, step: "code", debug: result };
  } catch (err) {
    return { ok: false, step: "error", error: `Ошибка: ${err instanceof Error ? err.message : err}` };
  }
}

// --- Step 2: Submit captcha ---

export async function cdpSubmitCaptcha(captchaText: string): Promise<AuthStepResult> {
  try {
    const page = await getPage();

    const result = await page.evaluate(async (code: string) => {
      const res = await fetch("/auth/v2/auth/slide-v3-confirm", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "wb-apptype": "web",
          "wb-appversion": "v1.91.0",
          "app-name": "seller.seller-auth",
          "locale": "ru",
        },
        credentials: "include",
        body: JSON.stringify({ captchaCode: code }),
      });
      return { status: res.status, data: await res.json().catch(() => null) };
    }, captchaText);

    const d = result.data as Record<string, unknown> | null;
    if (d?.sticker) g.__wbCdpSticker = d.sticker as string;

    if (d && (d.result as number) === 0) {
      return { ok: true, step: "code", debug: d };
    }

    return { ok: false, step: "error", error: `Captcha error: ${JSON.stringify(d)}`, debug: d };
  } catch (err) {
    return { ok: false, step: "error", error: `Ошибка капчи: ${err instanceof Error ? err.message : err}` };
  }
}

// --- Step 3: Submit SMS code ---

export async function cdpSubmitCode(code: string): Promise<AuthStepResult> {
  try {
    const page = await getPage();
    const digits = code.replace(/\D/g, "");

    // Check page is on WB
    const currentUrl = page.url();
    if (!currentUrl.includes("wildberries")) {
      await closeBrowser();
      return { ok: false, step: "error", error: "Сессия браузера потеряна. Нажмите «Назад» и введите номер заново." };
    }

    console.log("[wb-auth-cdp] Entering SMS code via page UI...");

    // Set up CDP to intercept the auth response
    const client = await page.createCDPSession();
    await client.send("Network.enable");

    let authToken = "";
    const tokenPromise = new Promise<string>((resolve) => {
      const timeout = setTimeout(() => resolve(""), 25000);
      client.on("Network.responseReceived", async (params: { requestId: string; response: { url: string; status: number } }) => {
        if (params.response.url.includes("/auth/v2/auth") && !params.response.url.includes("slide") && !params.response.url.includes("upgrade")) {
          try {
            const { body } = await client.send("Network.getResponseBody", { requestId: params.requestId });
            const data = JSON.parse(body);
            console.log("[wb-auth-cdp] Auth response:", JSON.stringify(data));
            if (data.result === 0 && data.payload?.access_token) {
              clearTimeout(timeout);
              resolve(data.payload.access_token);
            } else if (data.result === 17) {
              clearTimeout(timeout);
              resolve("INCORRECT_CODE");
            } else if (data.result === 8) {
              clearTimeout(timeout);
              resolve("EXPIRED_TOKEN");
            }
          } catch {}
        }
      });
    });

    // Find code input cells and type digits
    await new Promise(r => setTimeout(r, 1000));
    let codeCells = await page.$$('input[class*="InputCell"]');
    if (codeCells.length < 4) {
      const allNumeric = await page.$$('input[inputmode="numeric"]');
      const filtered = [];
      for (const el of allNumeric) {
        const isPhoneField = await el.evaluate(e =>
          e.placeholder.includes("999") || e.className.includes("SimpleInput")
        );
        if (!isPhoneField) filtered.push(el);
      }
      if (filtered.length >= 4) codeCells = filtered;
    }

    if (codeCells.length >= 4) {
      for (let i = 0; i < Math.min(digits.length, codeCells.length); i++) {
        await codeCells[i].click();
        await codeCells[i].type(digits[i], { delay: 50 });
      }
    } else {
      await client.send("Network.disable");
      await client.detach();
      return { ok: false, step: "error", error: "Не найдены поля ввода кода" };
    }

    // Wait for auth response
    console.log("[wb-auth-cdp] Waiting for auth response...");
    authToken = await tokenPromise;

    await client.send("Network.disable");
    await client.detach();

    if (authToken === "INCORRECT_CODE") {
      return { ok: false, step: "error", error: "Неверный SMS-код" };
    }

    if (authToken === "EXPIRED_TOKEN") {
      return { ok: false, step: "error", error: "Токен истёк. Запросите код заново." };
    }

    if (authToken && authToken.length > 50) {
      await saveAuthTokens(page, authToken);
      await closeBrowser();
      const mismatch = checkSupplierMismatch();
      return {
        ok: true,
        step: "authenticated",
        warning: mismatch || undefined,
      };
    }

    // Fallback: check URL — maybe already redirected to seller
    await new Promise(r => setTimeout(r, 3000));
    const url = page.url();
    if (url.includes("seller.wildberries.ru") && !url.includes("seller-auth")) {
      // Capture token from page
      const cookies = await page.cookies();
      const wbToken = cookies.find(c => c.name === "WBTokenV3");
      if (wbToken) {
        await saveAuthTokens(page, wbToken.value);
        await closeBrowser();
        return { ok: true, step: "authenticated" };
      }
    }

    return { ok: false, step: "error", error: "Не удалось получить токен авторизации" };
  } catch (err) {
    return { ok: false, step: "error", error: `Ошибка кода: ${err instanceof Error ? err.message : err}` };
  }
}

// --- Supplier mismatch check ---

function checkSupplierMismatch(): string | null {
  try {
    const apiKeyPath = path.join(process.cwd(), "data", "wb-api-key.txt");
    if (!fs.existsSync(apiKeyPath)) return null;
    const apiKey = fs.readFileSync(apiKeyPath, "utf-8").trim();
    if (!apiKey) return null;

    // Decode API key JWT → oid
    const apiPayload = JSON.parse(Buffer.from(apiKey.split(".")[1], "base64").toString());
    const apiOid = String(apiPayload.oid || "");

    // Read saved tokens → supplierId
    const tokensPath = path.join(DATA_DIR, "wb-tokens.json");
    if (!fs.existsSync(tokensPath)) return null;
    const tokens = JSON.parse(fs.readFileSync(tokensPath, "utf-8"));
    const tokenSid = String(tokens.supplierId || "");

    if (apiOid && tokenSid && apiOid !== tokenSid) {
      console.warn(`[wb-auth-cdp] SUPPLIER MISMATCH! API key: ${apiOid}, Token: ${tokenSid}`);
      return `Внимание: API-ключ привязан к кабинету ${apiOid}, а авторизация — к кабинету ${tokenSid}. Финансовые отчёты будут от другого юрлица.`;
    }
    return null;
  } catch {
    return null;
  }
}

// --- Token extraction ---

async function saveAuthTokens(page: Page, authToken: string): Promise<void> {
  ensureDirs();

  // Navigate to seller portal to establish all cookies
  console.log("[wb-auth-cdp] Navigating to seller portal to get cookies...");
  await page.goto("https://seller.wildberries.ru/", {
    waitUntil: "domcontentloaded",
    timeout: 15000,
  }).catch(() => {});
  await new Promise(r => setTimeout(r, 3000));

  // Get all cookies via CDP (includes cross-domain)
  const client = await page.createCDPSession();
  const { cookies } = await client.send("Network.getAllCookies") as {
    cookies: Array<{ name: string; value: string; domain: string }>;
  };
  await client.detach();

  console.log("[wb-auth-cdp] Total cookies:", cookies.length);
  const cookieParts: string[] = [];
  for (const c of cookies) {
    if (c.name === "wbx-validation-key" || c.name === "x-supplier-id-external") {
      cookieParts.push(`${c.name}=${c.value}`);
      console.log(`[wb-auth-cdp] Cookie: ${c.name}=${c.value.slice(0, 20)}...`);
    }
  }

  await saveAuthTokensCommon(authToken, cookieParts.join("; "), "wb-auth-cdp");
}

// --- Session check ---

export async function cdpCheckSession(): Promise<{ ok: boolean; error?: string }> {
  return checkApiSession();
}

// --- Logout ---

export function cdpLogout(): void {
  g.__wbCdpSticker = "";
  closeBrowser().catch(() => {});
  const tokensPath = path.join(DATA_DIR, "wb-tokens.json");
  if (fs.existsSync(tokensPath)) fs.unlinkSync(tokensPath);
  const cookiesPath = path.join(DATA_DIR, "wb-cookies.json");
  if (fs.existsSync(cookiesPath)) fs.unlinkSync(cookiesPath);
}

"use client";

import { useState, useEffect, useRef } from "react";
import { AutoCheckLine } from "./AutoCheckLine";

type Step = "loading" | "phone" | "captcha" | "code" | "supplier_select" | "authenticated";

export function WbAuth() {
  const [step, setStep] = useState<Step>("loading");
  const [phone, setPhone] = useState("+7 (");

  function formatPhone(value: string): string {
    // Strip everything except digits
    const digits = value.replace(/\D/g, "");
    // Always start with 7
    const d = digits.startsWith("7") ? digits : "7" + digits;
    // Max 11 digits (7 + 10)
    const limited = d.slice(0, 11);
    // Format: +7 (XXX) XXX-XX-XX
    let result = "+7";
    if (limited.length > 1) result += " (" + limited.slice(1, 4);
    if (limited.length >= 4) result += ") ";
    if (limited.length > 4) result += limited.slice(4, 7);
    if (limited.length > 7) result += "-" + limited.slice(7, 9);
    if (limited.length > 9) result += "-" + limited.slice(9, 11);
    return result;
  }
  const [code, setCode] = useState("");
  const [captchaText, setCaptchaText] = useState("");
  const [captchaImage, setCaptchaImage] = useState("");
  const [suppliers, setSuppliers] = useState<string[]>([]);
  const [currentSupplier, setCurrentSupplier] = useState("");
  const [sessionInfo, setSessionInfo] = useState<{ supplier?: string; phone?: string }>({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [warning, setWarning] = useState("");
  const codeRef = useRef<HTMLInputElement>(null);
  const captchaRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    checkSession();
  }, []);

  // Auto-focus inputs when step changes
  useEffect(() => {
    if (step === "code") codeRef.current?.focus();
    if (step === "captcha") captchaRef.current?.focus();
  }, [step]);

  async function checkSession() {
    try {
      const res = await fetch("/api/wb/auth");
      const data = await res.json();
      if (data.ok) {
        setSessionInfo({ supplier: data.supplier, phone: data.phone });
        setStep("authenticated");
      } else {
        setStep("phone");
      }
    } catch {
      setStep("phone");
    }
  }

  function handleStepResult(data: { ok: boolean; step: string; captchaImage?: string; error?: string; warning?: string; suppliers?: string[]; currentSupplier?: string }) {
    if (!data.ok && data.step === "error") {
      setError(data.error || "Неизвестная ошибка");
      return;
    }

    // If wrong code — show error but stay on code step
    if (!data.ok && data.step === "code") {
      setError(data.error || "Неверный код");
      setCode("");
      setStep("code");
      return;
    }

    setError("");
    if (data.warning) setWarning(data.warning);

    switch (data.step) {
      case "captcha":
        setCaptchaImage(data.captchaImage || "");
        setCaptchaText("");
        setStep("captcha");
        break;
      case "code":
        setCode("");
        setStep("code");
        break;
      case "supplier_select":
        setSuppliers(data.suppliers || []);
        setCurrentSupplier(data.currentSupplier || "");
        setStep("supplier_select");
        break;
      case "authenticated":
        fetch("/api/wb/auth").then(r => r.json()).then(d => {
          if (d.ok) {
            setStep("authenticated");
          } else {
            setError("Авторизация прошла, но токены не сохранились. Попробуйте ещё раз.");
            setStep("phone");
          }
        }).catch(() => {
          setStep("authenticated");
        });
        break;
      default:
        setError(data.error || "Неожиданный ответ");
    }
  }

  async function handleSendPhone() {
    const cleaned = phone.replace(/[^\d+]/g, "");
    if (cleaned.length < 11) {
      setError("Введите корректный номер телефона");
      return;
    }

    setLoading(true);
    setError("");

    try {
      const res = await fetch("/api/wb/auth", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone: cleaned }),
      });
      handleStepResult(await res.json());
    } catch {
      setError("Ошибка соединения с сервером");
    } finally {
      setLoading(false);
    }
  }

  async function handleSubmitCaptcha() {
    if (!captchaText.trim()) {
      setError("Введите текст с картинки");
      return;
    }

    setLoading(true);
    setError("");

    try {
      const res = await fetch("/api/wb/auth/captcha", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ captcha: captchaText.trim() }),
      });
      handleStepResult(await res.json());
    } catch {
      setError("Ошибка соединения с сервером");
    } finally {
      setLoading(false);
    }
  }

  async function handleSubmitCode() {
    const cleaned = code.replace(/\D/g, "");
    if (cleaned.length < 4) {
      setError("Введите код из SMS");
      return;
    }

    setLoading(true);
    setError("");

    try {
      const res = await fetch("/api/wb/auth/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code: cleaned }),
      });
      handleStepResult(await res.json());
    } catch {
      setError("Ошибка соединения с сервером");
    } finally {
      setLoading(false);
    }
  }

  async function handleSelectSupplier(name: string) {
    setLoading(true);
    setError("");
    try {
      const res = await fetch("/api/wb/auth/select-supplier", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ supplier: name }),
      });
      handleStepResult(await res.json());
    } catch {
      setError("Ошибка соединения с сервером");
    } finally {
      setLoading(false);
    }
  }

  async function handleLogout() {
    setLoading(true);
    try {
      await fetch("/api/wb/auth", { method: "DELETE" });
    } catch {}
    setStep("phone");
    setPhone("+7 (");
    setCode("");
    setCaptchaText("");
    setCaptchaImage("");
    setError("");
    setLoading(false);
  }

  function handleBack() {
    setStep("phone");
    setCode("");
    setCaptchaText("");
    setCaptchaImage("");
    setError("");
  }

  return (
    <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-5">
      <div className="flex items-center justify-between mb-1">
        <h3 className="font-medium">Авторизация WB</h3>
        {(step === "captcha" || step === "code" || step === "supplier_select") && (
          <StepIndicator current={step} />
        )}
      </div>
      <AutoCheckLine channel="lk" />

      {/* Error banner */}
      {error && (
        <div className="mb-4 rounded-lg p-3 text-sm bg-[var(--danger)]/10 text-[var(--danger)] border border-[var(--danger)]/20">
          {error}
        </div>
      )}

      {/* --- LOADING --- */}
      {step === "loading" && (
        <div className="flex items-center gap-2 text-sm text-[var(--text-muted)]">
          <Spinner />
          Проверка сессии...
        </div>
      )}

      {/* --- PHONE INPUT --- */}
      {step === "phone" && (
        <div className="flex items-center gap-3">
          <input
            type="tel"
            value={phone}
            onChange={(e) => setPhone(formatPhone(e.target.value))}
            placeholder="+7 (900) 123-45-67"
            maxLength={18}
            className="w-52 bg-[var(--bg)] border border-[var(--border)] rounded-lg px-4 py-2.5 text-sm tracking-wide focus:outline-none focus:border-[var(--accent)] transition-colors"
            onKeyDown={(e) => e.key === "Enter" && handleSendPhone()}
            disabled={loading}
          />
          <button
            onClick={handleSendPhone}
            disabled={loading}
            className="px-5 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-hover)] text-white text-sm rounded-lg font-medium transition-colors disabled:opacity-50 flex items-center gap-2"
          >
            {loading && <Spinner />}
            {loading ? "Подключение..." : "Получить код"}
          </button>
        </div>
      )}

      {/* --- CAPTCHA --- */}
      {step === "captcha" && (
        <div className="space-y-4">
          <div className="rounded-lg border border-[var(--warning)]/30 bg-[var(--warning)]/5 p-3 text-sm text-[var(--warning)]">
            WB запросил капчу. Введите текст с картинки.
          </div>

          {captchaImage && (
            <div className="flex justify-center">
              <img
                src={`data:image/png;base64,${captchaImage}`}
                alt="Капча"
                className="rounded-lg border border-[var(--border)] max-w-full"
                style={{ imageRendering: "crisp-edges" }}
              />
            </div>
          )}

          <div className="flex items-center gap-3">
            <input
              ref={captchaRef}
              type="text"
              value={captchaText}
              onChange={(e) => setCaptchaText(e.target.value)}
              placeholder="Текст с картинки"
              className="w-48 bg-[var(--bg)] border border-[var(--border)] rounded-lg px-4 py-2.5 text-sm text-center tracking-wider focus:outline-none focus:border-[var(--accent)] transition-colors"
              onKeyDown={(e) => e.key === "Enter" && handleSubmitCaptcha()}
              disabled={loading}
            />
            <button
              onClick={handleSubmitCaptcha}
              disabled={loading}
              className="px-5 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-hover)] text-white text-sm rounded-lg font-medium transition-colors disabled:opacity-50 flex items-center gap-2"
            >
              {loading && <Spinner />}
              {loading ? "Отправка..." : "Отправить"}
            </button>
            <button onClick={handleBack} disabled={loading} className="btn-secondary">
              Назад
            </button>
          </div>
        </div>
      )}

      {/* --- SMS CODE --- */}
      {step === "code" && (
        <div className="space-y-3">
          <div className="rounded-lg border border-[var(--accent)]/30 bg-[var(--accent)]/5 p-3 text-sm text-[var(--accent)]">
            SMS-код отправлен на <span className="font-medium">{phone}</span>
          </div>

          <div className="flex items-center gap-3">
            <input
              ref={codeRef}
              type="text"
              inputMode="numeric"
              value={code}
              onChange={(e) => setCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
              placeholder="Код из SMS"
              maxLength={6}
              className="w-40 bg-[var(--bg)] border border-[var(--border)] rounded-lg px-4 py-2.5 text-base text-center tracking-widest focus:outline-none focus:border-[var(--accent)] transition-colors"
              onKeyDown={(e) => e.key === "Enter" && handleSubmitCode()}
              disabled={loading}
            />
            <button
              onClick={handleSubmitCode}
              disabled={loading}
              className="px-5 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-hover)] text-white text-sm rounded-lg font-medium transition-colors disabled:opacity-50 flex items-center gap-2"
            >
              {loading && <Spinner />}
              {loading ? "Проверка..." : "Подтвердить"}
            </button>
            <button onClick={handleBack} disabled={loading} className="btn-secondary">
              Назад
            </button>
          </div>
        </div>
      )}

      {/* --- SUPPLIER SELECT --- */}
      {step === "supplier_select" && (
        <div className="space-y-3">
          <div className="rounded-lg border border-[var(--accent)]/30 bg-[var(--accent)]/5 p-3 text-sm text-[var(--accent)]">
            К номеру <span className="font-medium">{phone}</span> привязано несколько кабинетов. Выберите нужный:
          </div>

          <div className="space-y-2">
            {suppliers.map((name) => (
              <button
                key={name}
                onClick={() => handleSelectSupplier(name)}
                disabled={loading}
                className={`w-full text-left px-4 py-3 rounded-lg border text-sm font-medium transition-colors flex items-center justify-between ${
                  name === currentSupplier
                    ? "border-[var(--accent)] bg-[var(--accent)]/10 text-[var(--accent)]"
                    : "border-[var(--border)] bg-[var(--bg)] text-[var(--text)] hover:border-[var(--accent)]/50"
                } disabled:opacity-50`}
              >
                <span>{name}</span>
                {name === currentSupplier && <span className="text-xs text-[var(--text-muted)]">текущий</span>}
              </button>
            ))}
          </div>

          <button onClick={handleBack} disabled={loading} className="btn-secondary text-sm">
            Назад
          </button>
        </div>
      )}

      {/* --- AUTHENTICATED --- */}
      {step === "authenticated" && (
        <div className="space-y-3">
          {warning && (
            <div className="rounded-lg p-3 text-sm bg-[var(--warning)]/10 text-[var(--warning)] border border-[var(--warning)]/20">
              {warning}
            </div>
          )}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                <span className="w-2.5 h-2.5 rounded-full bg-[var(--success)] animate-pulse" />
                <span className="text-xs text-[var(--text-muted)]">Статус</span>
                <span className="text-sm font-medium text-[var(--success)]">Активен</span>
              </div>
              {sessionInfo.supplier && (
                <div className="flex items-center gap-2 border-l border-[var(--border)] pl-4">
                  <span className="text-xs text-[var(--text-muted)]">Кабинет</span>
                  <span className="text-sm font-medium text-[var(--text)]">{sessionInfo.supplier}</span>
                </div>
              )}
              {sessionInfo.phone && (
                <div className="flex items-center gap-2 border-l border-[var(--border)] pl-4">
                  <span className="text-xs text-[var(--text-muted)]">Телефон</span>
                  <span className="text-sm font-mono text-[var(--text)]">{sessionInfo.phone}</span>
                </div>
              )}
            </div>
            <button
              onClick={handleLogout}
              disabled={loading}
              className="px-4 py-2 border border-[var(--danger)]/30 text-[var(--danger)] text-sm rounded-lg font-medium hover:bg-[var(--danger)]/10 transition-colors disabled:opacity-50"
            >
              Выйти
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function Spinner() {
  return (
    <svg className="animate-spin h-4 w-4" viewBox="0 0 24 24" fill="none">
      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
    </svg>
  );
}

function StepIndicator({ current }: { current: "captcha" | "code" | "supplier_select" }) {
  const steps = [
    { key: "phone", label: "Телефон" },
    { key: "code", label: "SMS" },
    { key: "supplier_select", label: "Кабинет" },
  ];

  const currentIdx = current === "captcha" ? 1 : current === "code" ? 1 : 2;

  return (
    <div className="flex items-center gap-1.5 text-xs">
      {steps.map((s, i) => (
        <span key={s.key} className="flex items-center gap-1.5">
          <span
            className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold ${
              i < currentIdx
                ? "bg-[var(--success)] text-white"
                : i === currentIdx
                ? "bg-[var(--accent)] text-white"
                : "bg-[var(--border)] text-[var(--text-muted)]"
            }`}
          >
            {i < currentIdx ? "✓" : i + 1}
          </span>
          <span className={i === currentIdx ? "text-[var(--text)]" : "text-[var(--text-muted)]"}>
            {s.label}
          </span>
          {i < steps.length - 1 && <span className="text-[var(--border)] mx-0.5">—</span>}
        </span>
      ))}
    </div>
  );
}

import { NextRequest, NextResponse } from "next/server";
import { requireAdmin } from "@/lib/api-auth";
import { playwrightSendPhone, playwrightCheckSession, playwrightLogout } from "@/lib/wb-auth-playwright";
import fs from "fs";
import path from "path";

const TOKENS_PATH = path.join(process.cwd(), "data", "wb-tokens.json");

/**
 * POST /api/wb/auth — Start auth: send phone number (Playwright on VPS)
 * GET /api/wb/auth — Check if session is active + return session info
 * DELETE /api/wb/auth — Logout
 */

export async function POST(req: NextRequest) {
  const authError = requireAdmin(req);
  if (authError) return authError;

  try {
    const { phone } = await req.json();
    if (!phone) {
      return NextResponse.json({ ok: false, step: "error", error: "Укажите номер телефона" }, { status: 400 });
    }
    const result = await playwrightSendPhone(phone);
    return NextResponse.json(result);
  } catch (err) {
    return NextResponse.json({ ok: false, step: "error", error: String(err) }, { status: 500 });
  }
}

export async function GET(req: NextRequest) {
  const authError = requireAdmin(req);
  if (authError) return authError;

  try {
    const result = await playwrightCheckSession();

    // Enrich with session info from tokens
    if (result.ok) {
      let supplier = "";
      let phone = "";
      try {
        if (fs.existsSync(TOKENS_PATH)) {
          const tokens = JSON.parse(fs.readFileSync(TOKENS_PATH, "utf-8"));

          // Get supplier name from wbSellerLk JWT
          if (tokens.wbSellerLk) {
            try {
              const payload = JSON.parse(Buffer.from(tokens.wbSellerLk.split(".")[1], "base64").toString());
              const sd = payload.data || {};
              const sfid = sd["Z-Sfid"] || sd["Z-Soid"] || "";
              supplier = sfid ? `ИП (ID: ${sfid})` : "";
            } catch {}
          }

          // Try reading supplier name from last auth log
          try {
            const log = fs.readFileSync("/tmp/wb_auth_log.txt", "utf-8");
            const match = log.match(/supplier":\s*"([^"]+)"/);
            if (match) supplier = match[1];
          } catch {}

          // Get phone from saved tokens
          if (tokens.savedAt) {
            try {
              const log = fs.readFileSync("/tmp/wb_auth_log.txt", "utf-8");
              const match = log.match(/phone":\s*"(\d+)"/);
              if (match) {
                const d = match[1];
                phone = `+7 (${d.slice(0,3)}) ${d.slice(3,6)}-${d.slice(6,8)}-${d.slice(8,10)}`;
              }
            } catch {}
          }

          if (!supplier && tokens.supplierId) {
            supplier = `Кабинет ${tokens.supplierId}`;
          }
        }
      } catch {}

      return NextResponse.json({ ...result, supplier, phone });
    }

    return NextResponse.json(result);
  } catch (err) {
    return NextResponse.json({ ok: false, error: String(err) }, { status: 500 });
  }
}

export async function DELETE(req: NextRequest) {
  const authError = requireAdmin(req);
  if (authError) return authError;

  try {
    playwrightLogout();
    return NextResponse.json({ ok: true });
  } catch (err) {
    return NextResponse.json({ ok: false, error: String(err) }, { status: 500 });
  }
}

