// Keep alive 5 min
await new Promise(r => setTimeout(r, 300000));

fs.writeFileSync('data/wb-sniffed-requests.json', JSON.stringify(requests, null, 2));
console.log('Saved to data/wb-sniffed-requests.json');
await browser.close();
